// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool okFallback, ) = address(c).call{value: 1 ether}("");
        require(okFallback);

        RevertingReceiver receiver = new RevertingReceiver();
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(address(receiver), 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("always revert");
    }
}
